import {weeklyMetrics,releaseMetrics,SOURCE_DOCUMENT,densityMeasures} from './metrics.js';
import {escapeHTML as h,classificationLabels} from './report.js';

// Weekly and release definitions follow PDF pages 1-6 with noted website updates.
// Trend definitions describe the five charts currently generated by report.js.
// Scoring rules remain in metrics.js; this page does not calculate scores.
const titleCase=value=>value.replace(/\b[a-z]/g,letter=>letter.toUpperCase());
const weekly=weeklyMetrics.map(metric=>({
  ...metric,timing:'Weekly',
  note:metric.id==='open'?'The PDF calls this “Open P0/P1 defects (week-end)” and defines it as the open count at week-end. The website uses the updated escaped-defect label.':'',
}));
const release=releaseMetrics.map(metric=>({
  ...metric,
  timing:metric.group==='Product quality'?'Post-release (first 14 days)':['openAtRelease','averageCreated','open','aging'].includes(metric.id)?'At release time':'At release (final value)',
  ...(metric.id==='density'?{
    name:'Defect Density',
    formula:densityMeasures.map(m=>m.name+': '+m.formula).join('; '),
    note:'Updated website definition. Use one distinct confirmed defect population and the same release scope and cutoff for all three measures. Exclude duplicate and rejected non-defects; count reopened defects once. Count distinct executed test cases, not reruns, and requirements at a consistent level of detail. Use the fixed approved planned development effort baseline. Missing counts or zero denominators are unavailable. Previous man-days ratios are retained for reference only.',
  }:metric.id==='aging'?{
    formula:'(Resolved date - detected date) ÷ total days open',
    note:'The PDF formula is ambiguous. In the website, enter your measured average age in days; it is not calculated automatically.',
  }:metric.id==='reopened'?{
    note:'Corrected website formula. Use totals from the same release and measurement period. Enter the measured percentage directly; it is not calculated automatically. Leave the value blank (N/A) if the tested count is zero or either count is unavailable.',
  }:metric.id==='crashUsers'?{
    note:'For example, if 10 of 1,000 active users have one or more fatal crashes, the crash-free users rate is 99%. Use unique users across the full period, not an average of daily percentages. Leave the value blank (N/A) if there are no active users or data is unavailable.',
  }:metric.id==='uatDiscovery'?{
    note:'Updated website definition replacing the PDF’s Regression vs UAT defects comparison. Use distinct confirmed first discoveries for the same release and scope across all agreed pre-UAT stages and UAT. Both counts are required; a zero denominator is N/A. Previous regression-only counts are retained for verification, not treated as the complete pre-UAT population. Record P0/P1 UAT discoveries, including those subsequently fixed, and root causes separately. P0/P1 UAT discoveries are a subset of the total UAT discoveries. Supply an explicit zero if none were found.',
  }:metric.id==='averageCreated'?{
    note:'Calculated from saved weekly P0/P1-created counts. Divide their total by weeks with valid measured counts; include measured zeroes and exclude blanks. A previous manually entered average is not used.',
  }:['firstRun','flaky'].includes(metric.id)?{note:'If applicable; the PDF marks this metric “if any”.'}:{}),
}));
const trends=[
  {
    id:'created',name:'Overall Defects Created (Weekly) vs P0/P1 Defects Created (Weekly)',unit:'count',perspective:'development',
    formula:'Two count series for each week: all defects created and P0/P1 defects created.',
    note:'Overall-created counts come from saved or imported trend measurements. P0/P1-created counts come from Weekly Operational Metrics. Both series are informational and do not contribute to scores.',
    timing:'Weekly',source:'Saved trend measurements + weekly P0/P1 measurements (Jira)',
  },
  {
    id:'escaped',name:'Escaped P0/P1 Defects (Weekly)',unit:'count',perspective:'development',
    formula:weeklyMetrics.find(metric=>metric.id==='open').formula,
    note:'Uses the weekly Escaped P0/P1 defects (week-end) measurement, previously labeled Open P0/P1 defects (week-end).',
    timing:'Weekly (week-end)',source:'Weekly Operational Metrics (Jira)',
  },
  {
    id:'fixed',name:'Defects Fixed Rate (Weekly)',unit:'%',perspective:'development',
    formula:weeklyMetrics.find(metric=>metric.id==='fixed').formula,
    note:'Plots the entered weekly fixed-rate percentage. Leave blank if the created count is zero or either count is unavailable. Values above 100% are supported.',
    timing:'Weekly',source:'Weekly Operational Metrics (Jira)',
  },
  {
    id:'failed',name:'Defects Failed Rate (Weekly)',unit:'%',perspective:'development',
    formula:weeklyMetrics.find(metric=>metric.id==='reopened').formula,
    note:'The chart uses the entered weekly Defects reopened rate percentage. Reopened defects are those moved to QA Failed / UAT Failed; tested defects are those moved to QA In Progress / UAT In Progress. Leave blank if the tested count is zero or either count is unavailable.',
    timing:'Weekly',source:'Weekly Operational Metrics (Jira)',
  },
  {
    id:'score',name:'Score (Weekly)',unit:'points',perspectives:['qa','development'],
    formula:'Sum of RAG points for measured, scored weekly metrics ÷ number of those metrics (0–100).',
    note:'Each measured metric contributes 100 (Green), 60 (Amber), or 0 (Red) points. Includes QA and Development weekly metrics; excludes informational discovery counts and release metrics. Blank or invalid measurements are excluded; measured zeroes are included. A week with no scored measurements is N/A. See Scoring Methodology for thresholds.',
    timing:'Weekly',source:'Calculated from Weekly Operational Metrics',
  },
];

export const referenceSections=[
  {id:'reference-weekly',title:'Weekly Operational Metrics',items:weekly,description:'Measure defect flow, backlog health, and test execution each week.'},
  {id:'reference-trends',title:'Trend Charts',items:trends,description:'The five charts shown in the generated report, in report order. These definitions describe the website’s current chart selection. Missing values appear as gaps; measured zeroes are plotted. All chart series use every original reporting week, regardless of report filters.'},
  {id:'reference-release',title:'Release Summary Metrics',items:release,description:'Measure product quality during the first 14 days after release, and capture final release values for the other components.'},
];
export const defectStatuses=[
  {name:'Resolved defects',definition:'Defects moved to Ready for deploy / Done status.'},
  {name:'Reopened defects',definition:'Defects moved to QA Failed / UAT Failed status.'},
  {name:'Tested defects',definition:'Defects moved to QA In Progress / UAT In Progress status.'},
];

function referenceTable(items,id){
  return `<div class="table-scroll reference-scroll" role="region" aria-labelledby="${id}" tabindex="0"><table class="reference-table" aria-labelledby="${id}"><colgroup><col class="reference-metric-col"><col class="reference-definition-col"><col class="reference-timing-col"><col class="reference-source-col"></colgroup><thead><tr><th scope="col">Metric</th><th scope="col">Formula / Definition</th><th scope="col">Measurement Timing</th><th scope="col">Tool / Source</th></tr></thead><tbody>${items.map(metric=>`<tr data-reference-metric="${h(id+'-'+metric.id)}"><th scope="row"><span class="reference-metric-name">${h(metric.name)}</span>${(metric.perspectives??[metric.perspective]).map(perspective=>classificationLabels({perspective})).join('')}</th><td>${h(metric.formula)}${metric.note?(metric.id==='uatDiscovery'?`<ul class="metric-description reference-note">${metric.note.split('. ').map(text=>`<li>${h(text.endsWith('.')?text:text+'.')}</li>`).join('')}</ul>`:`<p class="reference-note">${h(metric.note)}</p>`):''}</td><td>${h(metric.timing)}</td><td>${h(metric.source)}</td></tr>`).join('')}</tbody></table></div>`;
}
function referenceSection(section){
  const groups=[...new Set(section.items.map(metric=>metric.group||'Trend Items'))];
  return `<section class="reference-section" aria-labelledby="${section.id}"><div class="reference-section-heading"><h2 id="${section.id}">${h(section.title)}</h2><span class="count-pill">${section.items.length} items</span></div><p class="report-note">${h(section.description)}</p>${groups.map((group,index)=>{
    const id=section.id+'-'+index,title=group==='Product quality'?'Product Quality (Customer & Production)':titleCase(group);
    return `<section class="panel reference-component"><div class="reference-component-heading"><h3 id="${id}">${h(title)}</h3></div>${referenceTable(section.items.filter(metric=>(metric.group||'Trend Items')===group),id)}</section>`;
  }).join('')}</section>`;
}
export function referenceDocument(){
  return `<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#18344f"><meta name="description" content="Weekly and release metric definitions, trend items, measurement timing, data sources, and defect statuses."><title>Quality Measurement · Metrics Reference</title><link rel="stylesheet" href="/styles.css"><link rel="stylesheet" href="/builder.css"><link rel="stylesheet" href="/print.css"></head><body class="standalone-report reference-page"><header class="reference-topbar"><a href="/#project" class="methodology-brand">Quality <span>Measurement</span></a><div><a class="button" href="/methodology.html">Scoring Methodology</a><a class="button" href="/#report">Generated Report</a></div></header><main><section class="report-intro"><div class="eyebrow">THE METRICS LIBRARY</div><h1>Metrics Reference</h1><p>Definitions, measurement timing, and data sources for weekly metrics, generated report charts, and release metrics.</p><div class="reference-counts"><span>9 weekly metrics</span><span>5 trend items</span><span>20 release metrics</span><span>3 status definitions</span></div></section><nav class="methodology-contents reference-contents" aria-label="Reference contents">${referenceSections.map(section=>`<a href="#${section.id}">${h(section.title)}</a>`).join('')}<a href="#reference-statuses">Defect Status Definitions</a></nav><p class="report-note reference-intro-note">Metric names and QA / Development labels align with the website. Notes identify updated wording and ambiguous source formulas. Percentage ratios are expressed as percentages for the website inputs.</p>${referenceSections.map(referenceSection).join('')}<section class="reference-section" aria-labelledby="reference-statuses"><div class="reference-section-heading"><h2 id="reference-statuses">Defect Status Definitions</h2><span class="count-pill">${defectStatuses.length} items</span></div><div class="panel"><table class="reference-table reference-status-table" aria-labelledby="reference-statuses"><thead><tr><th scope="col">Term</th><th scope="col">Definition</th></tr></thead><tbody>${defectStatuses.map(status=>`<tr data-reference-status><th scope="row">${h(status.name)}</th><td>${h(status.definition)}</td></tr>`).join('')}</tbody></table></div></section><p class="report-note reference-source">Source: ${h(SOURCE_DOCUMENT)}, definition tables and status notes on pages 1-6, with noted website updates. Trend Charts documents the current generated report.</p></main><footer><span>QUALITY MEASUREMENT <b>/</b> Engineering Quality</span><span>Metrics Reference</span></footer></body></html>`;
}
